-- =====================================================================
-- 0089 · EMILY (TL-053-26, v2): A PRIMEIRA FOLHA, DO BRIEFING APROVADO
--
-- Instrução dela, nov/26: "inclui a primeira página do resumo, de acordo
-- com o briefing que eu te mandei. Coloca os dados do voo e tudo mais."
--
-- A primeira folha da apresentada é a da Curadoria. Na v2 ela ainda era a
-- cópia do estudo — "first selection of hotels", com Borgo Vescine e La
-- Minerva, valores indicativos. Agora sai do briefing da advisor
-- (#/b/aa1224ef…, respondido pela Danielle em 8/11):
--   · voos, com a reserva e os horários, como estão no briefing;
--   · as três bases, Cortona dita como fora desta proposta;
--   · como eles se deslocam, com o carro que a Danielle respondeu
--     (BMW ou Mercedes SUV médio);
--   · o dia a dia, já com as respostas dela: Chianti no dia 27 (e não
--     Lucca), a joia feita para a Emily (colar ou pulseira, simples e
--     elegante), personal shopper no dia 2, e o fim da tarde do dia 2 em
--     aberto entre o Doria Pamphilj com jantar e a tarde livre;
--   · como eles viajam: independentes, com momentos organizados e acesso
--     a concierge.
--
-- Regra da 0062 aplicada: fica o que o programa É; sai o que a TL "fará"
-- antes de cotar ("we select an estate", "we design the route", "their
-- luggage has already gone ahead", "we will suggest a trattoria").
-- Os textos de venda das experiências entram depois, com a cotação de
-- cada dia.
--
-- Mexe só na v2 (e0530000-…-0002), sem link enviado e sem resposta.
-- Guardado: só troca se a folha ainda for a cópia do estudo (cita o
-- Borgo Vescine). A v1 não é tocada.
--
-- Seção 7: ops_proposals (update na v2), ops_migrations (insert).
-- =====================================================================

update ops_proposals set curations = E'[{"cor": "verde", "opcao": "", "title_en": "Emily & Nathan · Tuscany and Rome", "title_pt": "Emily & Nathan · Tuscany and Rome", "dest_en": "Florence · Cortona · Castelfalfi · Rome\\nJune 20 to July 3, 2027 · 13 nights", "dest_pt": "Florence · Cortona · Castelfalfi · Rome\\nJune 20 to July 3, 2027 · 13 nights", "dias_en": "Emily and Nathan land in Florence on Sunday, June 20, and fly home from Rome on Saturday, July 3. Thirteen nights: five in Cortona, four at Castelfalfi and four in Rome.\\n\\nFLIGHTS\\nBusiness class, booked by Fora · Delta reservation F8SCB6\\n- Sat, Jun 19: DL 9219, operated by KLM · Portland 1:05pm to Amsterdam 7:40am, Jun 20\\n- Sun, Jun 20: DL 9388, operated by KLM Cityhopper · Amsterdam 9:30am to Florence 11:30am\\n- Sat, Jul 3: DL 325 · Rome Fiumicino, Terminal 3, 12:20pm to Seattle 3:30pm\\n- Sat, Jul 3: DL 3913 · Seattle 5:40pm to Portland 6:43pm\\nPassport control is in Amsterdam, so the landing in Florence works like a domestic arrival.\\n\\nTHE NIGHTS\\n- Cortona: June 20 to 25, 5 nights, in a historic palace, not part of this proposal\\n- Castelfalfi, Montaione: June 25 to 29, 4 nights\\n- Bulgari Hotel Roma: June 29 to July 3, 4 nights\\n\\nGETTING AROUND\\n- Arrival: private transfer from Florence airport to Cortona, about 1h30\\n- Tuscany: a midsize BMW or Mercedes SUV, delivered in Cortona on June 21 and kept through the Castelfalfi days\\n- To Rome: on June 29 the Tuscan car is collected at Castelfalfi and a Ferrari takes its place for the drive; near Rome, a private transfer to the hotel\\n- Rome: no car; a private car on the days with experiences\\n- Departure: private transfer to Fiumicino, Terminal 3\\n\\nDAY BY DAY\\n- Sun, Jun 20 · Arrival: transfer to Cortona, the afternoon to settle in, an easy first walk through the town\\n- Mon, Jun 21 · Montalcino: the car is delivered in the morning; a Brunello estate with a visit and lunch\\n- Tue, Jun 22 · Montepulciano and Pienza: the two towns, and lunch at a farm-to-table restaurant\\n- Wed, Jun 23 · Arezzo and the goldsmith: Piazza Grande and a goldsmith''s workshop, with a piece made for Emily, a necklace or a bracelet, simple and elegant\\n- Thu, Jun 24 · A day of their own: the palace and the area, or Umbria next door, Orvieto or Deruta\\n- Fri, Jun 25 · Cortona to Castelfalfi: about 1h45 on the road, the afternoon at the resort\\n- Sat, Jun 26 · Truffles: a morning in the woods with a truffle hunter and his dogs, lunch with truffles, the afternoon at the resort\\n- Sun, Jun 27 · Chianti: wine estates and hilltop villages\\n- Mon, Jun 28 · Last day in Tuscany: a slow morning; in the afternoon a vintage car drive through the hills, with a picnic\\n- Tue, Jun 29 · To Rome by Ferrari: the drive from Castelfalfi, with a stretch along the coast or a stop in a village, and check-in at the Bulgari in the evening\\n- Wed, Jun 30 · The Colosseum: the underground at the first slot of the day, then the Colosseum and the Roman Forum with a private guide; the afternoon free\\n- Thu, Jul 1 · The Vatican with the Clavigero: the museums opened before the public, with a private guide; the afternoon free, and a sunset boat on the Tiber\\n- Fri, Jul 2 · Rome: a day in the boutiques around Via Condotti with a personal shopper; for the late afternoon, Palazzo Doria Pamphilj and a private dinner in a historic Roman residence, or the afternoon kept free\\n- Sat, Jul 3 · Departure: transfer to Fiumicino, leaving the hotel around 9:00\\n\\nHOW THEY TRAVEL\\nIndependently, with organized moments along the way and access to a concierge.", "dias_pt": "Emily and Nathan land in Florence on Sunday, June 20, and fly home from Rome on Saturday, July 3. Thirteen nights: five in Cortona, four at Castelfalfi and four in Rome.\\n\\nFLIGHTS\\nBusiness class, booked by Fora · Delta reservation F8SCB6\\n- Sat, Jun 19: DL 9219, operated by KLM · Portland 1:05pm to Amsterdam 7:40am, Jun 20\\n- Sun, Jun 20: DL 9388, operated by KLM Cityhopper · Amsterdam 9:30am to Florence 11:30am\\n- Sat, Jul 3: DL 325 · Rome Fiumicino, Terminal 3, 12:20pm to Seattle 3:30pm\\n- Sat, Jul 3: DL 3913 · Seattle 5:40pm to Portland 6:43pm\\nPassport control is in Amsterdam, so the landing in Florence works like a domestic arrival.\\n\\nTHE NIGHTS\\n- Cortona: June 20 to 25, 5 nights, in a historic palace, not part of this proposal\\n- Castelfalfi, Montaione: June 25 to 29, 4 nights\\n- Bulgari Hotel Roma: June 29 to July 3, 4 nights\\n\\nGETTING AROUND\\n- Arrival: private transfer from Florence airport to Cortona, about 1h30\\n- Tuscany: a midsize BMW or Mercedes SUV, delivered in Cortona on June 21 and kept through the Castelfalfi days\\n- To Rome: on June 29 the Tuscan car is collected at Castelfalfi and a Ferrari takes its place for the drive; near Rome, a private transfer to the hotel\\n- Rome: no car; a private car on the days with experiences\\n- Departure: private transfer to Fiumicino, Terminal 3\\n\\nDAY BY DAY\\n- Sun, Jun 20 · Arrival: transfer to Cortona, the afternoon to settle in, an easy first walk through the town\\n- Mon, Jun 21 · Montalcino: the car is delivered in the morning; a Brunello estate with a visit and lunch\\n- Tue, Jun 22 · Montepulciano and Pienza: the two towns, and lunch at a farm-to-table restaurant\\n- Wed, Jun 23 · Arezzo and the goldsmith: Piazza Grande and a goldsmith''s workshop, with a piece made for Emily, a necklace or a bracelet, simple and elegant\\n- Thu, Jun 24 · A day of their own: the palace and the area, or Umbria next door, Orvieto or Deruta\\n- Fri, Jun 25 · Cortona to Castelfalfi: about 1h45 on the road, the afternoon at the resort\\n- Sat, Jun 26 · Truffles: a morning in the woods with a truffle hunter and his dogs, lunch with truffles, the afternoon at the resort\\n- Sun, Jun 27 · Chianti: wine estates and hilltop villages\\n- Mon, Jun 28 · Last day in Tuscany: a slow morning; in the afternoon a vintage car drive through the hills, with a picnic\\n- Tue, Jun 29 · To Rome by Ferrari: the drive from Castelfalfi, with a stretch along the coast or a stop in a village, and check-in at the Bulgari in the evening\\n- Wed, Jun 30 · The Colosseum: the underground at the first slot of the day, then the Colosseum and the Roman Forum with a private guide; the afternoon free\\n- Thu, Jul 1 · The Vatican with the Clavigero: the museums opened before the public, with a private guide; the afternoon free, and a sunset boat on the Tiber\\n- Fri, Jul 2 · Rome: a day in the boutiques around Via Condotti with a personal shopper; for the late afternoon, Palazzo Doria Pamphilj and a private dinner in a historic Roman residence, or the afternoon kept free\\n- Sat, Jul 3 · Departure: transfer to Fiumicino, leaving the hotel around 9:00\\n\\nHOW THEY TRAVEL\\nIndependently, with organized moments along the way and access to a concierge."}]'::jsonb
 where id = 'e0530000-0000-0000-0000-000000000002'
   and responded_at is null
   and curations::text like '%Borgo Vescine%';

insert into ops_migrations (id) values ('0089-emily-v2-primeira-folha') on conflict (id) do nothing;
